mapper.select:
SELECT o.order_id, o.user_id, u.username, o.product_id, o.product_name,
       o.amount, o.status, o.receiver_addr, o.created_at_ms
FROM cw_order o
LEFT JOIN cw_user u ON u.tenant_id = o.tenant_id AND CAST(u.id AS BINARY) = CAST(o.user_id AS BINARY)
WHERE o.tenant_id = #{tenantId}
    AND CAST(o.user_id AS BINARY) = CAST(#{userId} AS BINARY)
    AND o.order_id = #{orderId}
    AND o.status = #{status}
    AND u.username LIKE CONCAT('%', #{username}, '%')
ORDER BY o.created_at_ms DESC
